syntax:
/*  Conceptual representation of glink functionality */
glink(caller_TOC_address, callee_TOC_address, callee_function_address) {
  push caller_TOC_address; // Save the caller's TOC
  load callee_TOC_address; // Load the callee's TOC
  jump callee_function_address; // Jump to the function in the callee module
  // ... upon return from callee_function_address ...
  pop caller_TOC_address; // Restore caller's TOC
  return;
}
